#include "NodeRuntime.h"
namespace { constexpr size_t INVALID_SLOT=NODE_RUNTIME_MAX_NODES; uint8_t priority(NodeRuntimeResult r){switch(r){case NodeRuntimeResult::INTERNAL_ERROR:return 8;case NodeRuntimeResult::SINK_REJECTED:return 7;case NodeRuntimeResult::TIMEOUT:return 6;case NodeRuntimeResult::SUCCESS:return 5;case NodeRuntimeResult::IN_PROGRESS:return 4;case NodeRuntimeResult::ACCEPTED:return 3;case NodeRuntimeResult::RETRY_LATER:return 2;case NodeRuntimeResult::NO_CHANGE:return 1;default:return 0;}} }
NodeRuntime::NodeRuntime(NodeRuntimeRegistry& r,NodeMessageSink& in,NodeOutboundSink& out):registry_(r),inboundSink_(in),outboundSink_(out),slots_{},slotCount_(0),initialized_(false){}
size_t NodeRuntime::findSlot(NodeId id)const{if(id==INVALID_NODE_ID)return INVALID_SLOT;for(size_t i=0;i<slotCount_;++i)if(slots_[i].descriptor&&slots_[i].descriptor->nodeId()==id)return i;return INVALID_SLOT;} NodeRuntimeResult NodeRuntime::higherPriority(NodeRuntimeResult a,NodeRuntimeResult b){return priority(b)>priority(a)?b:a;}
NodeRuntimeResult NodeRuntime::begin(NodeTimestamp now){if(initialized_)for(size_t i=0;i<slotCount_;++i)if(slots_[i].state.outboundBusy_)return NodeRuntimeResult::NODE_BUSY;if(registry_.lock()!=NodeRuntimeResult::SUCCESS){initialized_=false;return NodeRuntimeResult::INTERNAL_ERROR;}const size_t count=registry_.size();if(count>NODE_RUNTIME_MAX_NODES){initialized_=false;return NodeRuntimeResult::INTERNAL_ERROR;}for(size_t i=0;i<count;++i)if(!registry_.at(i)||!registry_.at(i)->isValid()){initialized_=false;return NodeRuntimeResult::INTERNAL_ERROR;}for(size_t i=0;i<NODE_RUNTIME_MAX_NODES;++i)slots_[i]=NodeRuntimeSlot{};slotCount_=count;for(size_t i=0;i<slotCount_;++i){NodeRuntimeSlot& s=slots_[i];s.descriptor=registry_.at(i);s.state.nodeId_=s.descriptor->nodeId();s.state.connectionState_=s.descriptor->enabled()?NodeConnectionState::UNKNOWN:NodeConnectionState::DISABLED;s.state.lastSeenAt_=0;s.state.lastStateChangeAt_=now;s.state.lastResult_=s.descriptor->enabled()?NodeRuntimeResult::SUCCESS:NodeRuntimeResult::NODE_DISABLED;s.state.activeOutboundMessageId_=0;s.state.outboundBusy_=false;s.hasBeenSeen=false;}initialized_=true;return NodeRuntimeResult::SUCCESS;}
bool NodeRuntime::isInitialized()const{return initialized_;}
NodeRuntimeResult NodeRuntime::handleInbound(const NodeInboundMessage& m,NodeTimestamp now){if(!initialized_)return NodeRuntimeResult::NOT_INITIALIZED;if(!m.isValid())return NodeRuntimeResult::INVALID_MESSAGE;size_t i=findSlot(m.sourceNodeId());if(i==INVALID_SLOT)return NodeRuntimeResult::NODE_NOT_FOUND;NodeRuntimeSlot& s=slots_[i];if(!s.descriptor->address().equals(m.sourceAddress()))return NodeRuntimeResult::INVALID_MESSAGE;if(!s.descriptor->enabled())return NodeRuntimeResult::NODE_DISABLED;s.state.lastSeenAt_=now;s.hasBeenSeen=true;if(s.state.connectionState_!=NodeConnectionState::ONLINE){s.state.connectionState_=NodeConnectionState::ONLINE;s.state.lastStateChangeAt_=now;}switch(inboundSink_.onNodeMessage(m)){case NodeMessageSinkResult::ACCEPTED:s.state.lastResult_=NodeRuntimeResult::SUCCESS;break;case NodeMessageSinkResult::REJECTED:s.state.lastResult_=NodeRuntimeResult::SINK_REJECTED;break;case NodeMessageSinkResult::RETRY_LATER:s.state.lastResult_=NodeRuntimeResult::RETRY_LATER;break;default:s.state.lastResult_=NodeRuntimeResult::INTERNAL_ERROR;}return s.state.lastResult_;}
NodeRuntimeResult NodeRuntime::send(NodeMessageId mid,NodeId id,const uint8_t* p,size_t n){if(!initialized_)return NodeRuntimeResult::NOT_INITIALIZED;if(mid==0)return NodeRuntimeResult::INVALID_ARGUMENT;size_t i=findSlot(id);if(i==INVALID_SLOT)return NodeRuntimeResult::NODE_NOT_FOUND;NodeRuntimeSlot& s=slots_[i];if(!s.descriptor->enabled())return NodeRuntimeResult::NODE_DISABLED;if(s.state.connectionState_!=NodeConnectionState::ONLINE)return NodeRuntimeResult::NODE_OFFLINE;if(!p||n==0||n>NODE_RUNTIME_MAX_PAYLOAD_LENGTH)return NodeRuntimeResult::INVALID_ARGUMENT;if(s.state.outboundBusy_)return NodeRuntimeResult::NODE_BUSY;switch(outboundSink_.sendToNode(mid,*s.descriptor,p,n)){case NodeOutboundSinkResult::SUCCESS:s.state.activeOutboundMessageId_=mid;s.state.lastResult_=NodeRuntimeResult::SUCCESS;return NodeRuntimeResult::SUCCESS;case NodeOutboundSinkResult::ACCEPTED:s.state.outboundBusy_=true;s.state.activeOutboundMessageId_=mid;s.state.lastResult_=NodeRuntimeResult::ACCEPTED;return NodeRuntimeResult::ACCEPTED;case NodeOutboundSinkResult::IN_PROGRESS:s.state.outboundBusy_=true;s.state.activeOutboundMessageId_=mid;s.state.lastResult_=NodeRuntimeResult::IN_PROGRESS;return NodeRuntimeResult::ACCEPTED;case NodeOutboundSinkResult::RETRY_LATER:s.state.lastResult_=NodeRuntimeResult::RETRY_LATER;return NodeRuntimeResult::RETRY_LATER;case NodeOutboundSinkResult::REJECTED:s.state.lastResult_=NodeRuntimeResult::SINK_REJECTED;return NodeRuntimeResult::SINK_REJECTED;default:s.state.lastResult_=NodeRuntimeResult::INTERNAL_ERROR;return NodeRuntimeResult::INTERNAL_ERROR;}}
NodeRuntimeResult NodeRuntime::update(NodeTimestamp now){if(!initialized_)return NodeRuntimeResult::NOT_INITIALIZED;NodeRuntimeResult overall=NodeRuntimeResult::NO_CHANGE;for(size_t i=0;i<slotCount_;++i){NodeRuntimeSlot& s=slots_[i];NodeRuntimeResult timeoutResult=NodeRuntimeResult::NO_CHANGE;NodeRuntimeResult outboundResult=NodeRuntimeResult::NO_CHANGE;if(s.descriptor->enabled()&&s.hasBeenSeen&&s.state.connectionState_!=NodeConnectionState::OFFLINE&&static_cast<NodeDuration>(now-s.state.lastSeenAt_)>=s.descriptor->offlineTimeoutMs()){s.state.connectionState_=NodeConnectionState::OFFLINE;s.state.lastStateChangeAt_=now;timeoutResult=NodeRuntimeResult::TIMEOUT;}if(s.state.outboundBusy_){switch(outboundSink_.updateNodeSend(s.descriptor->nodeId())){case NodeOutboundSinkResult::SUCCESS:s.state.outboundBusy_=false;s.state.activeOutboundMessageId_=0;outboundResult=NodeRuntimeResult::SUCCESS;break;case NodeOutboundSinkResult::ACCEPTED:outboundResult=NodeRuntimeResult::ACCEPTED;break;case NodeOutboundSinkResult::IN_PROGRESS:outboundResult=NodeRuntimeResult::IN_PROGRESS;break;case NodeOutboundSinkResult::RETRY_LATER:outboundResult=NodeRuntimeResult::RETRY_LATER;break;case NodeOutboundSinkResult::REJECTED:s.state.outboundBusy_=false;s.state.activeOutboundMessageId_=0;outboundResult=NodeRuntimeResult::SINK_REJECTED;break;default:s.state.outboundBusy_=false;s.state.activeOutboundMessageId_=0;outboundResult=NodeRuntimeResult::INTERNAL_ERROR;}}const NodeRuntimeResult slotResult=higherPriority(timeoutResult,outboundResult);if(slotResult!=NodeRuntimeResult::NO_CHANGE)s.state.lastResult_=slotResult;overall=higherPriority(overall,slotResult);}return overall;}
NodeRuntimeResult NodeRuntime::cancelSend(NodeId id){if(!initialized_)return NodeRuntimeResult::NOT_INITIALIZED;size_t i=findSlot(id);if(i==INVALID_SLOT)return NodeRuntimeResult::NODE_NOT_FOUND;NodeRuntimeState& s=slots_[i].state;if(!s.outboundBusy_)return NodeRuntimeResult::INVALID_ARGUMENT;switch(outboundSink_.cancelNodeSend(id)){case NodeOutboundSinkResult::SUCCESS:s.outboundBusy_=false;s.activeOutboundMessageId_=0;s.lastResult_=NodeRuntimeResult::SUCCESS;break;case NodeOutboundSinkResult::IN_PROGRESS:s.lastResult_=NodeRuntimeResult::IN_PROGRESS;break;case NodeOutboundSinkResult::RETRY_LATER:s.lastResult_=NodeRuntimeResult::RETRY_LATER;break;case NodeOutboundSinkResult::REJECTED:s.outboundBusy_=false;s.activeOutboundMessageId_=0;s.lastResult_=NodeRuntimeResult::SINK_REJECTED;break;default:s.outboundBusy_=false;s.activeOutboundMessageId_=0;s.lastResult_=NodeRuntimeResult::INTERNAL_ERROR;}return s.lastResult_;}
const NodeRuntimeState* NodeRuntime::state(NodeId id)const{size_t i=findSlot(id);return initialized_&&i!=INVALID_SLOT?&slots_[i].state:nullptr;} bool NodeRuntime::isOnline(NodeId id)const{const NodeRuntimeState* s=state(id);return s&&s->connectionState()==NodeConnectionState::ONLINE;} bool NodeRuntime::isBusy(NodeId id)const{const NodeRuntimeState* s=state(id);return s&&s->outboundBusy();}
